-- Generated from audited synthetic source. MySQL 8+. No DROP/REPLACE of databases.

CREATE DATABASE decision_studio CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;

USE decision_studio;

SET SESSION sql_mode='STRICT_TRANS_TABLES,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION';

CREATE TABLE `dim_channel` (
  `channel_id` BIGINT NOT NULL,
  `channel` VARCHAR(100) NOT NULL,
  PRIMARY KEY (`channel_id`)
) ENGINE=InnoDB;


CREATE TABLE `dim_category` (
  `category_id` BIGINT NOT NULL,
  `category` VARCHAR(100) NOT NULL,
  PRIMARY KEY (`category_id`)
) ENGINE=InnoDB;


CREATE TABLE `dim_customer` (
  `customer_id` BIGINT NOT NULL,
  `region` VARCHAR(100) NOT NULL,
  `city_tier` VARCHAR(100) NOT NULL,
  `acquisition_channel_id` BIGINT NOT NULL,
  `first_order_date` DATE NULL,
  PRIMARY KEY (`customer_id`),
  FOREIGN KEY (`acquisition_channel_id`) REFERENCES `dim_channel` (`channel_id`)
) ENGINE=InnoDB;

















CREATE TABLE `dim_product` (
  `product_id` BIGINT NOT NULL,
  `category_id` BIGINT NOT NULL,
  `product` VARCHAR(100) NOT NULL,
  `list_price_paise` BIGINT NOT NULL,
  CHECK (`list_price_paise` >= 0),
  `unit_cost_paise` BIGINT NOT NULL,
  CHECK (`unit_cost_paise` >= 0),
  PRIMARY KEY (`product_id`),
  FOREIGN KEY (`category_id`) REFERENCES `dim_category` (`category_id`)
) ENGINE=InnoDB;


CREATE TABLE `dim_date` (
  `date` DATE NOT NULL,
  `month` VARCHAR(100) NOT NULL,
  `year` BIGINT NOT NULL,
  `month_number` BIGINT NOT NULL,
  PRIMARY KEY (`date`)
) ENGINE=InnoDB;



CREATE TABLE `fact_orders` (
  `order_id` VARCHAR(100) NOT NULL,
  `customer_id` BIGINT NOT NULL,
  `order_date` DATE NOT NULL,
  `category_id` BIGINT NOT NULL,
  `channel_id` BIGINT NOT NULL,
  `payment_method` VARCHAR(100) NOT NULL,
  `promised_date` DATE NOT NULL,
  `delivered_date` DATE NULL,
  `status` VARCHAR(100) NOT NULL,
  `gross_paise` BIGINT NOT NULL,
  CHECK (`gross_paise` >= 0),
  `discount_paise` BIGINT NOT NULL,
  CHECK (`discount_paise` >= 0),
  `refund_paise` BIGINT NOT NULL,
  CHECK (`refund_paise` >= 0),
  `cogs_paise` BIGINT NOT NULL,
  CHECK (`cogs_paise` >= 0),
  `recovered_inventory_paise` BIGINT NOT NULL,
  CHECK (`recovered_inventory_paise` >= 0),
  `fulfilment_paise` BIGINT NOT NULL,
  CHECK (`fulfilment_paise` >= 0),
  `payment_fee_paise` BIGINT NOT NULL,
  CHECK (`payment_fee_paise` >= 0),
  `reverse_logistics_paise` BIGINT NOT NULL,
  CHECK (`reverse_logistics_paise` >= 0),
  `return_flag` BIGINT NOT NULL,
  `late_flag` BIGINT NOT NULL,
  `delivery_eligible` BIGINT NOT NULL,
  `return_mature` BIGINT NOT NULL,
  `new_customer` BIGINT NOT NULL,
  `net_sales_paise` BIGINT NOT NULL,
  `net_product_cost_paise` BIGINT NOT NULL,
  `contribution_before_marketing_paise` BIGINT NOT NULL,
  PRIMARY KEY (`order_id`),
  FOREIGN KEY (`customer_id`) REFERENCES `dim_customer` (`customer_id`),
  FOREIGN KEY (`category_id`) REFERENCES `dim_category` (`category_id`),
  FOREIGN KEY (`channel_id`) REFERENCES `dim_channel` (`channel_id`),
  FOREIGN KEY (`order_date`) REFERENCES `dim_date` (`date`)
) ENGINE=InnoDB;





























































CREATE TABLE `fact_order_items` (
  `line_id` VARCHAR(100) NOT NULL,
  `order_id` VARCHAR(100) NOT NULL,
  `product_id` BIGINT NOT NULL,
  `quantity` BIGINT NOT NULL,
  `gross_paise` BIGINT NOT NULL,
  CHECK (`gross_paise` >= 0),
  `discount_paise` BIGINT NOT NULL,
  CHECK (`discount_paise` >= 0),
  `cogs_paise` BIGINT NOT NULL,
  CHECK (`cogs_paise` >= 0),
  PRIMARY KEY (`line_id`),
  FOREIGN KEY (`order_id`) REFERENCES `fact_orders` (`order_id`),
  FOREIGN KEY (`product_id`) REFERENCES `dim_product` (`product_id`)
) ENGINE=InnoDB;


























































































































CREATE TABLE `fact_marketing` (
  `date` DATE NOT NULL,
  `channel_id` BIGINT NOT NULL,
  `spend_paise` BIGINT NOT NULL,
  CHECK (`spend_paise` >= 0),
  PRIMARY KEY (`date`,`channel_id`),
  FOREIGN KEY (`date`) REFERENCES `dim_date` (`date`),
  FOREIGN KEY (`channel_id`) REFERENCES `dim_channel` (`channel_id`)
) ENGINE=InnoDB;








CREATE SQL SECURITY INVOKER VIEW vw_order_economics AS SELECT * FROM fact_orders;
